-- Aprenda se Divertindo · 104 · Simulado 1 da Trilha Administrativa
-- Rode depois do 103-simulado-tribunais-1.sql. Cole tudo no SQL Editor e clique em Run.
-- Cria e publica o Simulado 1 da trilha Administrativa: abre no sábado, 07/11/2026, às 0h, e fecha no domingo, 08/11/2026, às 23h59.
-- 100 questões de A a E, estilo FGV, 4 horas de prova.
-- Português 15 (com redação oficial), Raciocínio Lógico 8, Informática 8, Constitucional 10, Administrativo 15, Gestão 10,
-- Arquivologia 8, AFO 6, Previdência 12, Pessoa com Deficiência 3, Sustentabilidade 3, Inteligência Artificial 2.
-- Gabarito equilibrado: 20 questões com cada letra. Gabarito comentado na segunda, 09/11, às 0h.
-- Rodar de novo atualiza as questões, desde que ninguém tenha começado a prova.

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "Durante décadas, o cidadão brasileiro associou o serviço público à fila. Era preciso chegar cedo, levar cópias de todos os documentos e, muitas vezes, voltar no dia seguinte porque faltava um carimbo. A digitalização mudou boa parte desse cenário: hoje, muitos serviços podem ser pedidos pelo celular, sem sair de casa. Seria ingênuo, contudo, imaginar que a tecnologia resolveu tudo.\n\nPara uma parcela significativa da população, o atendimento digital ainda é uma barreira, e não uma facilidade. Idosos, pessoas com pouca escolaridade e moradores de regiões sem boa conexão continuam precisando de alguém do outro lado do balcão. Um serviço público de qualidade, portanto, não é aquele que elimina o atendimento presencial, mas aquele que oferece caminhos diferentes para pessoas diferentes.", "enunciado": "De acordo com o texto, a digitalização dos serviços públicos", "opcoes": ["tornou as filas mais longas para quem usa o celular.", "resolveu os problemas de quem mora longe da conexão.", "trouxe avanços, mas não atende igualmente a todos.", "eliminou a necessidade de atendimento presencial no país.", "foi rejeitada pela maior parte dos cidadãos brasileiros."], "gabarito": 2, "explicacao": "“Seria ingênuo, contudo, imaginar que a tecnologia resolveu tudo.”"}, {"materia": "port", "texto_base": "Durante décadas, o cidadão brasileiro associou o serviço público à fila. Era preciso chegar cedo, levar cópias de todos os documentos e, muitas vezes, voltar no dia seguinte porque faltava um carimbo. A digitalização mudou boa parte desse cenário: hoje, muitos serviços podem ser pedidos pelo celular, sem sair de casa. Seria ingênuo, contudo, imaginar que a tecnologia resolveu tudo.\n\nPara uma parcela significativa da população, o atendimento digital ainda é uma barreira, e não uma facilidade. Idosos, pessoas com pouca escolaridade e moradores de regiões sem boa conexão continuam precisando de alguém do outro lado do balcão. Um serviço público de qualidade, portanto, não é aquele que elimina o atendimento presencial, mas aquele que oferece caminhos diferentes para pessoas diferentes.", "enunciado": "Para o autor, um serviço público de qualidade é aquele que", "opcoes": ["atende primeiro quem chega mais cedo à repartição.", "prioriza a tecnologia, ainda que parte do público fique de fora.", "oferece formas diferentes de atendimento a públicos diferentes.", "substitui de vez o balcão pelo atendimento feito pelo celular.", "exige cópias de todos os documentos para evitar fraudes."], "gabarito": 2, "explicacao": "“Oferece caminhos diferentes para pessoas diferentes.”"}, {"materia": "port", "texto_base": "Durante décadas, o cidadão brasileiro associou o serviço público à fila. Era preciso chegar cedo, levar cópias de todos os documentos e, muitas vezes, voltar no dia seguinte porque faltava um carimbo. A digitalização mudou boa parte desse cenário: hoje, muitos serviços podem ser pedidos pelo celular, sem sair de casa. Seria ingênuo, contudo, imaginar que a tecnologia resolveu tudo.\n\nPara uma parcela significativa da população, o atendimento digital ainda é uma barreira, e não uma facilidade. Idosos, pessoas com pouca escolaridade e moradores de regiões sem boa conexão continuam precisando de alguém do outro lado do balcão. Um serviço público de qualidade, portanto, não é aquele que elimina o atendimento presencial, mas aquele que oferece caminhos diferentes para pessoas diferentes.", "enunciado": "No fim do primeiro parágrafo, a palavra “contudo” pode ser substituída, sem mudar o sentido, por", "opcoes": ["porque.", "portanto.", "assim.", "além disso.", "no entanto."], "gabarito": 4, "explicacao": "Ambas indicam oposição."}, {"materia": "port", "texto_base": "Durante décadas, o cidadão brasileiro associou o serviço público à fila. Era preciso chegar cedo, levar cópias de todos os documentos e, muitas vezes, voltar no dia seguinte porque faltava um carimbo. A digitalização mudou boa parte desse cenário: hoje, muitos serviços podem ser pedidos pelo celular, sem sair de casa. Seria ingênuo, contudo, imaginar que a tecnologia resolveu tudo.\n\nPara uma parcela significativa da população, o atendimento digital ainda é uma barreira, e não uma facilidade. Idosos, pessoas com pouca escolaridade e moradores de regiões sem boa conexão continuam precisando de alguém do outro lado do balcão. Um serviço público de qualidade, portanto, não é aquele que elimina o atendimento presencial, mas aquele que oferece caminhos diferentes para pessoas diferentes.", "enunciado": "Em “porque faltava um carimbo”, a oração introduzida por “porque” expressa", "opcoes": ["concessão.", "consequência.", "finalidade.", "causa.", "condição."], "gabarito": 3, "explicacao": "Explica o motivo de voltar no dia seguinte."}, {"materia": "port", "texto_base": "Durante décadas, o cidadão brasileiro associou o serviço público à fila. Era preciso chegar cedo, levar cópias de todos os documentos e, muitas vezes, voltar no dia seguinte porque faltava um carimbo. A digitalização mudou boa parte desse cenário: hoje, muitos serviços podem ser pedidos pelo celular, sem sair de casa. Seria ingênuo, contudo, imaginar que a tecnologia resolveu tudo.\n\nPara uma parcela significativa da população, o atendimento digital ainda é uma barreira, e não uma facilidade. Idosos, pessoas com pouca escolaridade e moradores de regiões sem boa conexão continuam precisando de alguém do outro lado do balcão. Um serviço público de qualidade, portanto, não é aquele que elimina o atendimento presencial, mas aquele que oferece caminhos diferentes para pessoas diferentes.", "enunciado": "No trecho “é uma barreira, e não uma facilidade”, está subentendido, depois de “não”, o verbo", "opcoes": ["“faltava”, que aparece no primeiro parágrafo.", "“precisando”, que vem na frase seguinte.", "“resolveu”, do fim do primeiro parágrafo.", "“é”, já expresso antes na mesma oração.", "“oferece”, do último período do texto."], "gabarito": 3, "explicacao": "Elipse: “e não é uma facilidade”."}, {"materia": "port", "texto_base": "Durante décadas, o cidadão brasileiro associou o serviço público à fila. Era preciso chegar cedo, levar cópias de todos os documentos e, muitas vezes, voltar no dia seguinte porque faltava um carimbo. A digitalização mudou boa parte desse cenário: hoje, muitos serviços podem ser pedidos pelo celular, sem sair de casa. Seria ingênuo, contudo, imaginar que a tecnologia resolveu tudo.\n\nPara uma parcela significativa da população, o atendimento digital ainda é uma barreira, e não uma facilidade. Idosos, pessoas com pouca escolaridade e moradores de regiões sem boa conexão continuam precisando de alguém do outro lado do balcão. Um serviço público de qualidade, portanto, não é aquele que elimina o atendimento presencial, mas aquele que oferece caminhos diferentes para pessoas diferentes.", "enunciado": "No último período, a palavra “portanto” introduz", "opcoes": ["uma oposição ao que foi dito antes.", "uma conclusão do raciocínio anterior.", "uma condição para o bom atendimento.", "um exemplo de serviço feito pelo celular.", "uma explicação da causa das filas."], "gabarito": 1, "explicacao": "Conjunção conclusiva."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase em que a concordância está correta.", "opcoes": ["Mais de um servidor faltou à reunião.", "Haviam muitas reclamações na ouvidoria.", "Vende-se casas no centro da cidade.", "Os Estados Unidos é parceiro comercial do Brasil.", "Fazem dois meses que o pedido foi feito."], "gabarito": 0, "explicacao": "Com “mais de um”, o verbo fica em regra no singular. “Fazer” (tempo) e “haver” (existir) são impessoais."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase em que o acento indicativo de crase está correto.", "opcoes": ["O servidor começou à atender cedo.", "Refiro-me à esta solicitação.", "Ficou cara à cara com o chefe do setor.", "Entreguei o ofício à Vossa Senhoria.", "O atendimento vai das 8h às 17h."], "gabarito": 4, "explicacao": "Há crase na indicação de horas. Não há antes de verbo, em palavras repetidas, de pronome de tratamento e de “esta”."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase com a forma verbal correta.", "opcoes": ["Quando ele propor a mudança, avise o chefe.", "Se o servidor ver o erro, deve corrigi-lo.", "Quando eles reaverem o documento, liguem.", "Se o servidor vir o erro, deve corrigi-lo.", "Se você manter o prazo, tudo ficará bem."], "gabarito": 3, "explicacao": "Futuro do subjuntivo: vir (ver), propuser, mantiver, reouverem."}, {"materia": "port", "texto_base": "", "enunciado": "Pelo Manual de Redação da Presidência da República, o pronome de tratamento usado para ministro de Estado é", "opcoes": ["Vossa Excelência.", "Meritíssimo.", "Vossa Eminência.", "Vossa Senhoria.", "Vossa Magnificência."], "gabarito": 0, "explicacao": "Usado para altas autoridades dos três Poderes."}, {"materia": "port", "texto_base": "", "enunciado": "Pelo Manual de Redação da Presidência da República, o fecho “Atenciosamente” é usado em comunicações dirigidas a", "opcoes": ["autoridades de mesma hierarquia ou de hierarquia inferior.", "chefes de Estado estrangeiros, em qualquer caso.", "autoridades de hierarquia superior, inclusive o Presidente.", "particulares, apenas, e nunca a outras autoridades.", "ministros do STF, em todos os ofícios oficiais."], "gabarito": 0, "explicacao": "Para autoridades superiores, usa-se “Respeitosamente”."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase em que a palavra está grafada de acordo com o Acordo Ortográfico.", "opcoes": ["O sub-solo do prédio foi reformado.", "A anti-sala estava cheia de pessoas.", "O autoatendimento reduziu as filas.", "O auto-atendimento reduziu as filas.", "A semi-final será disputada amanhã."], "gabarito": 2, "explicacao": "Sem hífen quando o prefixo termina em vogal e a palavra começa por consoante diferente de r e s: autoatendimento, subsolo, semifinal, antessala."}, {"materia": "port", "texto_base": "", "enunciado": "Em “O servidor entregou o protocolo à cidadã”, o termo “à cidadã” é", "opcoes": ["complemento nominal.", "objeto direto.", "objeto indireto.", "adjunto adverbial.", "agente da passiva."], "gabarito": 2, "explicacao": "Entregar algo a alguém."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase escrita de acordo com a norma-padrão.", "opcoes": ["Fazem dez anos que ele trabalha no INSS.", "Ele trabalha no INSS há dez anos atrás.", "Daqui há dez anos ele se aposenta.", "Há dez anos ele trabalha no INSS.", "A dez anos ele trabalha no INSS."], "gabarito": 3, "explicacao": "“Há” indica tempo passado; “daqui a” indica futuro; “há… atrás” é redundante."}, {"materia": "port", "texto_base": "", "enunciado": "A palavra “atendimento” é formada por", "opcoes": ["derivação sufixal.", "derivação prefixal.", "composição por justaposição.", "derivação regressiva.", "derivação parassintética."], "gabarito": 0, "explicacao": "atender + -mento."}, {"materia": "rl", "texto_base": "", "enunciado": "Ou o processo está no arquivo, ou está na mesa do chefe. O processo não está na mesa do chefe. Logo,", "opcoes": ["o processo está na mesa do chefe.", "o processo não está no arquivo.", "o processo foi extraviado.", "nada se pode concluir.", "o processo está no arquivo."], "gabarito": 4, "explicacao": "Silogismo disjuntivo."}, {"materia": "rl", "texto_base": "", "enunciado": "A negação de “Alguns servidores trabalham aos sábados” é:", "opcoes": ["Alguns servidores não trabalham aos sábados.", "Nenhum servidor trabalha aos sábados.", "Todos os servidores trabalham aos sábados.", "Nem todos os servidores trabalham aos sábados.", "Todos os servidores não trabalham aos domingos."], "gabarito": 1, "explicacao": "A negação de “algum” é “nenhum”."}, {"materia": "rl", "texto_base": "", "enunciado": "Um setor atende 120 pessoas por dia com 4 atendentes. Com 6 atendentes, no mesmo ritmo, atenderá", "opcoes": ["150 pessoas.", "240 pessoas.", "180 pessoas.", "200 pessoas.", "160 pessoas."], "gabarito": 2, "explicacao": "30 pessoas por atendente × 6."}, {"materia": "rl", "texto_base": "", "enunciado": "Um salário de R$ 2.000,00 teve aumento de 10% e, depois, outro de 10%. O novo salário é de", "opcoes": ["R$ 2.200,00.", "R$ 2.440,00.", "R$ 2.420,00.", "R$ 2.400,00.", "R$ 2.410,00."], "gabarito": 2, "explicacao": "2.000 × 1,1 × 1,1."}, {"materia": "rl", "texto_base": "", "enunciado": "Numa repartição há 8 homens e 12 mulheres. Escolhendo uma pessoa ao acaso, a probabilidade de ser mulher é", "opcoes": ["1/12.", "3/2.", "2/5.", "1/2.", "3/5."], "gabarito": 4, "explicacao": "12/20."}, {"materia": "rl", "texto_base": "", "enunciado": "Uma senha de atendimento tem uma letra (entre 26) seguida de dois algarismos (de 0 a 9). Quantas senhas diferentes existem?", "opcoes": ["2.700", "260", "2.600", "2.340", "676"], "gabarito": 2, "explicacao": "26 × 10 × 10."}, {"materia": "rl", "texto_base": "", "enunciado": "Se hoje é quarta-feira, daqui a 100 dias será", "opcoes": ["sábado.", "quinta-feira.", "domingo.", "quarta-feira.", "sexta-feira."], "gabarito": 4, "explicacao": "100 = 14 × 7 + 2: dois dias depois de quarta."}, {"materia": "rl", "texto_base": "", "enunciado": "Na sequência 2, 5, 14, 41, …, cada termo é o triplo do anterior menos 1. O próximo termo é", "opcoes": ["123.", "120.", "82.", "122.", "124."], "gabarito": 3, "explicacao": "41 × 3 − 1."}, {"materia": "inf", "texto_base": "", "enunciado": "No Excel, a fórmula =SOMA(A1:A3)/3 dá o mesmo resultado que", "opcoes": ["=MÍNIMO(A1:A3), se os valores das células forem iguais.", "=MÁXIMO(A1:A3), em qualquer caso.", "=MÉDIA(A1:A3), se as três células tiverem números.", "=SOMA(A1;A3)/3, sempre.", "=CONT.NÚM(A1:A3), se não houver texto."], "gabarito": 2, "explicacao": "A média é a soma dividida pela quantidade de valores."}, {"materia": "inf", "texto_base": "", "enunciado": "No Excel, o resultado de =CONCATENAR(\"INSS\";\"-\";\"BA\") é", "opcoes": ["#VALOR!", "INSSBA", "INSS-BA", "INSS;-;BA", "INSS BA"], "gabarito": 2, "explicacao": "Junta os textos na ordem."}, {"materia": "inf", "texto_base": "", "enunciado": "Ao receber e-mail de remetente desconhecido com anexo .exe, a atitude mais segura é", "opcoes": ["não abrir o anexo e excluir a mensagem.", "salvar o anexo e abrir depois.", "encaminhar aos colegas para conferirem.", "abrir o anexo para ver do que se trata.", "responder pedindo mais informações."], "gabarito": 0, "explicacao": "Arquivos .exe podem conter programas maliciosos."}, {"materia": "inf", "texto_base": "", "enunciado": "No Windows, Ctrl + Shift + Esc abre o", "opcoes": ["Explorador de Arquivos.", "Painel de Controle.", "Menu Iniciar.", "Prompt de Comando.", "Gerenciador de Tarefas."], "gabarito": 4, "explicacao": "Atalho direto, sem passar pela tela do Ctrl + Alt + Del."}, {"materia": "inf", "texto_base": "", "enunciado": "No Word, o sumário automático é montado a partir dos", "opcoes": ["estilos de título aplicados ao texto.", "cabeçalhos e rodapés das páginas.", "marcadores e numerações das listas.", "comentários inseridos durante a revisão do texto.", "quebras de página do documento."], "gabarito": 0, "explicacao": "Título 1, Título 2 etc."}, {"materia": "inf", "texto_base": "", "enunciado": "A computação em nuvem permite, por exemplo,", "opcoes": ["impedir qualquer ataque de vírus.", "acessar arquivos de qualquer lugar com internet.", "aumentar a memória RAM do computador.", "dispensar senhas para entrar nos sistemas do órgão.", "usar o computador sem energia elétrica."], "gabarito": 1, "explicacao": "Os dados ficam em servidores remotos."}, {"materia": "inf", "texto_base": "", "enunciado": "Na navegação pela internet, um cookie é", "opcoes": ["um tipo de firewall que bloqueia sites falsos.", "um arquivo que o site grava no navegador para guardar dados.", "um servidor de e-mail usado pelo site visitado.", "um vírus que se instala no computador para roubar senhas bancárias.", "um programa antivírus embutido no navegador."], "gabarito": 1, "explicacao": "Guarda preferências, sessões e dados de navegação."}, {"materia": "inf", "texto_base": "", "enunciado": "Na maioria dos programas, o atalho Ctrl + P serve para", "opcoes": ["salvar.", "criar parágrafo.", "pesquisar.", "imprimir.", "colar."], "gabarito": 3, "explicacao": "P de print."}, {"materia": "const", "texto_base": "", "enunciado": "São direitos sociais previstos no art. 6º da Constituição, entre outros,", "opcoes": ["nacionalidade, cidadania e direitos políticos.", "vida, liberdade, igualdade, segurança e propriedade.", "educação, saúde, alimentação, trabalho e moradia.", "soberania, cidadania, dignidade e pluralismo político.", "habeas corpus, habeas data e mandado de segurança."], "gabarito": 2, "explicacao": "A vida, a liberdade e a propriedade estão no art. 5º."}, {"materia": "const", "texto_base": "", "enunciado": "Pela Constituição, o salário mínimo deve ser", "opcoes": ["fixado em lei e nacionalmente unificado.", "fixado pelo sindicato de cada categoria.", "fixado por cada estado, conforme o custo de vida.", "vinculado à cotação do dólar no mês.", "diferente para cada profissão regulamentada."], "gabarito": 0, "explicacao": "Art. 7º, IV, da CF."}, {"materia": "const", "texto_base": "", "enunciado": "A seguridade social compreende ações nas áreas de", "opcoes": ["segurança pública e defesa civil.", "habitação, transporte urbano e saneamento básico.", "trabalho, emprego e renda.", "saúde, previdência e assistência social.", "educação, cultura e esporte."], "gabarito": 3, "explicacao": "Art. 194 da CF."}, {"materia": "const", "texto_base": "", "enunciado": "Pela Constituição, a saúde é", "opcoes": ["direito apenas de quem contribui para o INSS.", "responsabilidade só dos planos privados.", "serviço pago, com isenção para os mais pobres.", "dever exclusivo dos municípios, sem a União.", "direito de todos e dever do Estado."], "gabarito": 4, "explicacao": "Art. 196 da CF."}, {"materia": "const", "texto_base": "", "enunciado": "Pela Constituição, a assistência social é prestada", "opcoes": ["a quem dela necessitar, independentemente de contribuição.", "só às pessoas com mais de 65 anos de idade.", "a quem pagar uma taxa mensal ao município.", "apenas a quem contribuiu para a seguridade social por 15 anos.", "somente aos servidores públicos e aos seus dependentes."], "gabarito": 0, "explicacao": "Art. 203 da CF."}, {"materia": "const", "texto_base": "", "enunciado": "São brasileiros natos, entre outros,", "opcoes": ["os filhos de brasileiros nascidos no exterior, em qualquer caso, sem registro.", "os naturalizados que vivem no Brasil há mais de 15 anos ininterruptos.", "os nascidos no Brasil, de pais estrangeiros que não sirvam a seu país.", "os portugueses com residência permanente no país, por reciprocidade.", "os estrangeiros que moram no Brasil há mais de 5 anos, sem condenação penal."], "gabarito": 2, "explicacao": "Art. 12, I, a, da CF."}, {"materia": "const", "texto_base": "", "enunciado": "São privativos de brasileiro nato, entre outros, os cargos de", "opcoes": ["governador e prefeito.", "Presidente da República e ministro do STF.", "ministro de Estado da Fazenda.", "juiz de direito, promotor de justiça e delegado.", "senador e deputado federal."], "gabarito": 1, "explicacao": "Art. 12, § 3º, da CF."}, {"materia": "const", "texto_base": "", "enunciado": "Quanto ao direito de greve dos servidores públicos civis, o STF decidiu que", "opcoes": ["ele depende de autorização prévia do chefe de cada Poder.", "ele é proibido em qualquer caso, por ser o serviço público essencial.", "aplica-se, até haver lei específica, a lei de greve do setor privado.", "ele pode ser exercido sem nenhum limite ou regra de funcionamento.", "ele só vale para os servidores federais, e não para os estaduais."], "gabarito": 2, "explicacao": "MI 670, 708 e 712."}, {"materia": "const", "texto_base": "", "enunciado": "A remuneração dos servidores públicos só pode ser fixada ou alterada por", "opcoes": ["resolução do próprio órgão.", "acordo coletivo.", "decreto do Executivo.", "portaria do ministério.", "lei específica."], "gabarito": 4, "explicacao": "Art. 37, X, da CF."}, {"materia": "const", "texto_base": "", "enunciado": "No âmbito da União, o teto remuneratório corresponde ao subsídio mensal dos", "opcoes": ["desembargadores dos tribunais.", "Presidente e Vice-Presidente da República.", "ministros do Supremo Tribunal Federal.", "ministros de Estado do Executivo.", "deputados federais e senadores."], "gabarito": 2, "explicacao": "Art. 37, XI, da CF."}, {"materia": "adm", "texto_base": "", "enunciado": "São princípios expressos no art. 37 da Constituição: legalidade, impessoalidade, moralidade, publicidade e", "opcoes": ["segurança jurídica.", "proporcionalidade.", "supremacia do interesse público.", "eficiência.", "razoabilidade."], "gabarito": 3, "explicacao": "Os demais são princípios implícitos ou previstos em outras leis."}, {"materia": "adm", "texto_base": "", "enunciado": "O ato que a Administração deve praticar, sem margem de escolha, quando cumpridos os requisitos da lei, é o ato", "opcoes": ["precário.", "complexo.", "discricionário.", "enunciativo.", "vinculado."], "gabarito": 4, "explicacao": "A lei define todos os seus elementos."}, {"materia": "adm", "texto_base": "", "enunciado": "A licença para construir, concedida a quem cumpre os requisitos legais, é ato", "opcoes": ["vinculado.", "revogável a qualquer tempo.", "precário.", "discricionário.", "negocial bilateral."], "gabarito": 0, "explicacao": "Diferente da autorização, que é discricionária."}, {"materia": "adm", "texto_base": "", "enunciado": "A autorização administrativa, como a de porte de arma de fogo, é, em regra, ato", "opcoes": ["bilateral e contratual.", "vinculado e definitivo.", "vinculado e irrevogável.", "normativo, geral e abstrato.", "discricionário e precário."], "gabarito": 4, "explicacao": "Pode ser revogada por conveniência."}, {"materia": "adm", "texto_base": "", "enunciado": "O poder regulamentar permite ao chefe do Executivo", "opcoes": ["criar tributos por meio de decreto.", "criar cargos públicos por decreto.", "revogar leis aprovadas pelo Congresso Nacional.", "expedir decretos para a fiel execução das leis.", "punir servidores sem processo."], "gabarito": 3, "explicacao": "Art. 84, IV, da CF."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 8.112/1990, a posse pode ser feita por procuração?", "opcoes": ["Só se o servidor estiver doente.", "Sim, por procuração genérica.", "Só com autorização do juiz.", "Não, em hipótese alguma.", "Sim, por procuração específica."], "gabarito": 4, "explicacao": "Art. 13, § 3º, da Lei 8.112/1990."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 8.112/1990, o servidor empossado que não entra em exercício no prazo legal é", "opcoes": ["removido.", "exonerado.", "demitido.", "advertido.", "suspenso."], "gabarito": 1, "explicacao": "Art. 15, § 2º, da Lei 8.112/1990."}, {"materia": "adm", "texto_base": "", "enunciado": "No estágio probatório, a Lei 8.112/1990 avalia, entre outros fatores,", "opcoes": ["assiduidade, disciplina, iniciativa, produtividade e responsabilidade.", "filiação partidária, sindicato e opinião política.", "idade, estado civil, religião, renda e local de moradia.", "popularidade entre os colegas, aparência pessoal e simpatia no atendimento.", "número de filhos, tempo de casa, salário e escolaridade."], "gabarito": 0, "explicacao": "Art. 20 da Lei 8.112/1990."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 8.112/1990, a licença por motivo de doença em pessoa da família é concedida", "opcoes": ["em qualquer caso, a pedido verbal do servidor.", "se a assistência direta do servidor for indispensável.", "apenas se o familiar morar em outra cidade.", "só se o servidor tiver mais de 10 anos de serviço.", "somente para doença do próprio servidor ou do cônjuge."], "gabarito": 1, "explicacao": "Art. 83 da Lei 8.112/1990."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 8.112/1990, é proibido ao servidor", "opcoes": ["exercer o direito de petição.", "representar contra ilegalidade ou abuso.", "recusar fé a documentos públicos.", "fazer curso de pós-graduação.", "filiar-se a um sindicato."], "gabarito": 2, "explicacao": "Art. 117, III. As demais condutas são permitidas ou deveres."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 8.112/1990, a demissão é aplicada, entre outros casos, por", "opcoes": ["atraso de 10 minutos no expediente.", "uso de roupa inadequada.", "improbidade administrativa.", "falta de um dia ao serviço.", "recusa a fazer hora extra."], "gabarito": 2, "explicacao": "Art. 132, IV, da Lei 8.112/1990."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 9.784/1999, concluída a instrução, a Administração tem para decidir prazo de até", "opcoes": ["90 dias, prorrogável por mais 30 dias.", "15 dias, sem prorrogação.", "60 dias, sem prorrogação.", "10 dias, prorrogável por mais 5.", "30 dias, prorrogável por igual período."], "gabarito": 4, "explicacao": "Art. 49 da Lei 9.784/1999."}, {"materia": "adm", "texto_base": "", "enunciado": "Na Lei 14.133/2021, a fase preparatória da licitação inclui, entre outros,", "opcoes": ["o estudo técnico preliminar e o termo de referência.", "a homologação do resultado final.", "o pagamento ao fornecedor contratado.", "a assinatura do contrato com o vencedor.", "a aplicação de penalidades ao contratado inadimplente."], "gabarito": 0, "explicacao": "Art. 18 da Lei 14.133/2021."}, {"materia": "adm", "texto_base": "", "enunciado": "Na Lei 14.133/2021, os contratos de serviços contínuos podem ter vigência de até", "opcoes": ["10 anos, prorrogáveis até 20.", "1 ano, sem prorrogação.", "60 meses, sem nenhuma prorrogação.", "2 anos, prorrogáveis até 4.", "5 anos, prorrogáveis até 10 anos."], "gabarito": 4, "explicacao": "Arts. 106 e 107 da Lei 14.133/2021."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela LGPD, o poder público deve tratar dados pessoais para", "opcoes": ["atender à finalidade pública e ao interesse público.", "divulgar dados de qualquer cidadão nas redes sociais.", "atender a interesses particulares do servidor.", "obter lucro com a venda de dados a empresas parceiras.", "formar listas de devedores para cobrança privada."], "gabarito": 0, "explicacao": "Art. 23 da Lei 13.709/2018."}, {"materia": "gest", "texto_base": "", "enunciado": "Para Fayol, as funções administrativas são", "opcoes": ["prever, organizar, comandar, coordenar e controlar.", "produzir, vender, cobrar, investir e lucrar.", "contratar, treinar, avaliar e demitir.", "informar, decidir, delegar e cobrar.", "planejar, executar, verificar e agir."], "gabarito": 0, "explicacao": "Elementos da administração (POCCC)."}, {"materia": "gest", "texto_base": "", "enunciado": "Na pirâmide de Maslow, a necessidade que fica na base é a", "opcoes": ["de segurança.", "de autorrealização.", "de estima.", "fisiológica.", "social."], "gabarito": 3, "explicacao": "Alimento, água, sono."}, {"materia": "gest", "texto_base": "", "enunciado": "Para Herzberg, são fatores motivacionais", "opcoes": ["a política da empresa e o estilo de supervisão.", "o reconhecimento e o próprio conteúdo do trabalho.", "o relacionamento com colegas e a estabilidade.", "os benefícios e a limpeza do ambiente.", "o salário e as condições físicas do local de trabalho."], "gabarito": 1, "explicacao": "Os demais são fatores higiênicos."}, {"materia": "gest", "texto_base": "", "enunciado": "A administração pública gerencial tem como foco", "opcoes": ["o formalismo e a hierarquia acima de qualquer resultado.", "os resultados e o cidadão como usuário dos serviços.", "a nomeação de parentes para cargos de confiança.", "a confusão entre o patrimônio público e o privado.", "o controle rígido dos procedimentos internos."], "gabarito": 1, "explicacao": "Reforma do Estado de 1995 (PDRAE)."}, {"materia": "gest", "texto_base": "", "enunciado": "O planejamento estratégico é responsabilidade, principalmente,", "opcoes": ["dos clientes do serviço.", "dos fornecedores externos.", "dos supervisores de equipe.", "dos estagiários do setor.", "da alta administração."], "gabarito": 4, "explicacao": "Define objetivos de longo prazo para toda a organização."}, {"materia": "gest", "texto_base": "", "enunciado": "O organograma representa", "opcoes": ["o fluxo de caixa mensal.", "a estrutura formal da organização.", "a cultura informal e os valores da equipe.", "o cronograma de um projeto.", "as etapas de um processo."], "gabarito": 1, "explicacao": "Mostra órgãos, cargos e relações de subordinação."}, {"materia": "gest", "texto_base": "", "enunciado": "A delegação consiste em", "opcoes": ["transferir autoridade para o subordinado decidir.", "dividir o salário entre os membros da equipe.", "concentrar todas as decisões no chefe do setor.", "demitir o servidor que comete falta grave.", "eliminar níveis hierárquicos da organização."], "gabarito": 0, "explicacao": "A responsabilidade final continua com quem delega."}, {"materia": "gest", "texto_base": "", "enunciado": "Na liderança situacional de Hersey e Blanchard, para uma equipe muito madura, o estilo indicado é", "opcoes": ["determinar.", "persuadir.", "compartilhar.", "delegar.", "impor."], "gabarito": 3, "explicacao": "Baixa orientação para tarefa e para relacionamento."}, {"materia": "gest", "texto_base": "", "enunciado": "Um indicador de eficácia mede", "opcoes": ["o impacto social de longo prazo.", "a rapidez de cada servidor.", "o custo de cada atendimento.", "o grau de alcance das metas.", "o número de servidores do setor."], "gabarito": 3, "explicacao": "Eficiência mede recursos; efetividade, impacto."}, {"materia": "gest", "texto_base": "", "enunciado": "Benchmarking é", "opcoes": ["copiar integralmente o regulamento de outro órgão público do país.", "medir apenas o lucro da organização ao final de cada ano.", "comparar práticas com as de organizações de referência.", "demitir os servidores com pior desempenho na avaliação anual.", "contratar consultoria externa para administrar o órgão inteiro."], "gabarito": 2, "explicacao": "Aprendizado com as melhores práticas."}, {"materia": "arq", "texto_base": "", "enunciado": "Documento de arquivo é aquele produzido ou recebido", "opcoes": ["apenas com valor histórico reconhecido.", "no exercício das atividades de uma instituição ou pessoa.", "para ser vendido em bibliotecas e livrarias.", "somente em papel, com assinatura à mão da autoridade responsável.", "apenas por órgãos públicos, nunca por particulares."], "gabarito": 1, "explicacao": "Art. 2º da Lei 8.159/1991."}, {"materia": "arq", "texto_base": "", "enunciado": "No método numérico simples, os documentos são ordenados", "opcoes": ["pelo nome do interessado, em ordem alfabética.", "pela data de chegada, do mais novo ao mais antigo.", "pelo número atribuído a cada documento ou pasta.", "pela cidade de origem do documento.", "pelo assunto, conforme o plano de classificação."], "gabarito": 2, "explicacao": "Costuma exigir índice auxiliar."}, {"materia": "arq", "texto_base": "", "enunciado": "No arquivamento alfabético de pessoas físicas, considera-se, em regra,", "opcoes": ["o apelido pelo qual a pessoa é conhecida.", "o último sobrenome, seguido do prenome.", "o nome do meio, seguido do último sobrenome.", "o primeiro nome, seguido do sobrenome.", "o sobrenome da mãe, seguido do prenome."], "gabarito": 1, "explicacao": "Ex.: Silva, João Carlos."}, {"materia": "arq", "texto_base": "", "enunciado": "Pelas regras de arquivamento alfabético, “José de Souza Filho” é arquivado como", "opcoes": ["José de Souza Filho.", "De Souza Filho, José.", "Souza Filho, José de.", "Filho, José de Souza.", "Souza, José de, Filho."], "gabarito": 2, "explicacao": "Graus de parentesco acompanham o sobrenome."}, {"materia": "arq", "texto_base": "", "enunciado": "A microfilmagem e a digitalização são exemplos de", "opcoes": ["protocolo de documentos.", "classificação de documentos.", "avaliação de documentos.", "eliminação de documentos.", "reprodução de documentos."], "gabarito": 4, "explicacao": "Geram cópias em outro suporte."}, {"materia": "arq", "texto_base": "", "enunciado": "O arquivo permanente guarda documentos de valor", "opcoes": ["apenas administrativo, de uso imediato.", "financeiro, para venda futura.", "pessoal, sem interesse público.", "histórico, probatório e informativo.", "temporário, até o fim do prazo."], "gabarito": 3, "explicacao": "Valor secundário; guarda definitiva."}, {"materia": "arq", "texto_base": "", "enunciado": "A Lei 8.159/1991 dispõe sobre", "opcoes": ["a proteção de dados pessoais em meio digital.", "as licitações e os contratos administrativos.", "o regime jurídico dos servidores federais.", "a política nacional de arquivos públicos e privados.", "o acesso à informação pública e as regras de sigilo."], "gabarito": 3, "explicacao": "Lei de Arquivos."}, {"materia": "arq", "texto_base": "", "enunciado": "Pela Lei 8.159/1991, a gestão de documentos abrange", "opcoes": ["a produção, a tramitação, o uso, a avaliação e o arquivamento.", "apenas a eliminação dos documentos sem valor, depois do prazo de guarda.", "apenas o empréstimo de documentos a pesquisadores externos.", "somente a digitalização dos documentos em papel do arquivo central.", "só a guarda dos documentos históricos no arquivo permanente."], "gabarito": 0, "explicacao": "Art. 3º da Lei 8.159/1991."}, {"materia": "afo", "texto_base": "", "enunciado": "O plano plurianual (PPA) tem vigência de", "opcoes": ["10 anos.", "5 anos.", "2 anos.", "1 ano.", "4 anos."], "gabarito": 4, "explicacao": "Art. 165, § 1º, da CF e ADCT, art. 35."}, {"materia": "afo", "texto_base": "", "enunciado": "A lei de diretrizes orçamentárias orienta a elaboração da", "opcoes": ["lei de licitações.", "lei orçamentária anual.", "lei de responsabilidade fiscal.", "lei orgânica do município.", "Constituição estadual."], "gabarito": 1, "explicacao": "Art. 165, § 2º, da CF."}, {"materia": "afo", "texto_base": "", "enunciado": "O princípio orçamentário da universalidade determina que", "opcoes": ["todas as receitas e despesas constem do orçamento.", "o orçamento seja aprovado por unanimidade.", "só as despesas com pessoal e custeio constem do orçamento.", "o orçamento valha por quatro anos.", "cada órgão tenha um orçamento separado."], "gabarito": 0, "explicacao": "Art. 2º da Lei 4.320/1964."}, {"materia": "afo", "texto_base": "", "enunciado": "O princípio do equilíbrio orçamentário busca", "opcoes": ["aumento anual das despesas com pessoal.", "igualdade entre receitas e despesas previstas.", "eliminação de todos os tributos.", "receitas sempre menores que as despesas.", "despesas sempre iguais às do exercício anterior, corrigidas."], "gabarito": 1, "explicacao": "Evita déficits."}, {"materia": "afo", "texto_base": "", "enunciado": "São receitas correntes, entre outras, as receitas", "opcoes": ["de transferências de capital entre entes.", "tributária, de contribuições e patrimonial.", "de operações de crédito e de alienação de bens.", "de venda de imóveis do patrimônio público.", "de amortização de empréstimos concedidos."], "gabarito": 1, "explicacao": "Art. 11, § 1º, da Lei 4.320/1964. As demais são de capital."}, {"materia": "afo", "texto_base": "", "enunciado": "A dívida ativa é formada por créditos da Fazenda Pública", "opcoes": ["perdoados por lei de anistia.", "que ainda não venceram nem foram lançados.", "devidos pela Fazenda a fornecedores.", "já pagos pelos contribuintes no prazo.", "inscritos após o vencimento e não pagos."], "gabarito": 4, "explicacao": "Art. 39 da Lei 4.320/1964."}, {"materia": "prev", "texto_base": "", "enunciado": "O Regime Geral de Previdência Social é administrado pelo", "opcoes": ["Instituto Nacional do Seguro Social (INSS).", "Banco Central do Brasil.", "Ministério da Saúde.", "Tribunal de Contas da União.", "Sistema Único de Saúde (SUS), nos municípios."], "gabarito": 0, "explicacao": "Autarquia federal."}, {"materia": "prev", "texto_base": "", "enunciado": "Após a EC 103/2019, a idade mínima da aposentadoria programada no RGPS, para quem trabalha na cidade, é de", "opcoes": ["70 anos para homens e 65 para mulheres.", "65 anos para homens e mulheres.", "60 anos para homens e 55 para mulheres.", "65 anos para homens e 62 para mulheres.", "62 anos para homens e 60 para mulheres."], "gabarito": 3, "explicacao": "Art. 201, § 7º, I, da CF."}, {"materia": "prev", "texto_base": "", "enunciado": "Na aposentadoria programada, o homem que se filiou ao RGPS depois da EC 103/2019 precisa de, no mínimo,", "opcoes": ["35 anos de contribuição.", "20 anos de contribuição.", "15 anos de contribuição.", "30 anos de contribuição.", "25 anos de contribuição."], "gabarito": 1, "explicacao": "Art. 19 da EC 103/2019. Para a mulher, 15 anos."}, {"materia": "prev", "texto_base": "", "enunciado": "O salário-maternidade da segurada, em regra, dura", "opcoes": ["30 dias.", "180 dias.", "60 dias.", "120 dias.", "90 dias."], "gabarito": 3, "explicacao": "Art. 71 da Lei 8.213/1991."}, {"materia": "prev", "texto_base": "", "enunciado": "No auxílio por incapacidade temporária do empregado, o INSS paga o benefício a partir do", "opcoes": ["60º dia de afastamento.", "16º dia de afastamento.", "30º dia de afastamento.", "8º dia de afastamento.", "1º dia de afastamento."], "gabarito": 1, "explicacao": "Os 15 primeiros dias ficam por conta da empresa (art. 60 da Lei 8.213/1991)."}, {"materia": "prev", "texto_base": "", "enunciado": "A pensão por morte é devida", "opcoes": ["ao empregador do segurado falecido.", "apenas aos filhos menores de 10 anos do segurado.", "aos dependentes do segurado que falecer.", "ao próprio segurado, ao se aposentar.", "a qualquer pessoa que pague o enterro."], "gabarito": 2, "explicacao": "Art. 74 da Lei 8.213/1991."}, {"materia": "prev", "texto_base": "", "enunciado": "O auxílio-reclusão é devido", "opcoes": ["à vítima do crime praticado pelo segurado preso.", "a qualquer preso, independentemente da renda e do regime de cumprimento.", "ao próprio preso, durante todo o cumprimento da pena.", "aos dependentes do preso em regime aberto, apenas.", "aos dependentes do segurado de baixa renda preso no regime fechado."], "gabarito": 4, "explicacao": "Art. 80 da Lei 8.213/1991, após a Lei 13.846/2019."}, {"materia": "prev", "texto_base": "", "enunciado": "É segurado obrigatório do RGPS como contribuinte individual", "opcoes": ["o estudante sem nenhuma atividade remunerada.", "o trabalhador autônomo que atua por conta própria.", "o empregado com carteira de trabalho assinada.", "o servidor efetivo vinculado a regime próprio.", "a pessoa que cuida só do lar, sem renda própria."], "gabarito": 1, "explicacao": "Art. 11, V, da Lei 8.213/1991."}, {"materia": "prev", "texto_base": "", "enunciado": "É exemplo de segurado facultativo do RGPS", "opcoes": ["quem cuida só da própria casa, sem renda.", "o trabalhador rural que produz em regime de economia familiar.", "o empregado doméstico com carteira assinada.", "o motorista de aplicativo que trabalha por conta própria.", "o empresário que recebe pró-labore da própria empresa."], "gabarito": 0, "explicacao": "Art. 13 da Lei 8.213/1991. As demais são seguradas obrigatórias."}, {"materia": "prev", "texto_base": "", "enunciado": "O Benefício de Prestação Continuada (BPC) garante", "opcoes": ["um auxílio temporário a quem perdeu o emprego com carteira assinada.", "uma pensão aos dependentes do segurado que faleceu sem deixar bens.", "meio salário mínimo a qualquer pessoa desempregada há mais de seis meses, sem renda.", "um salário mínimo à pessoa com deficiência ou ao idoso de 65 anos sem meios de se manter.", "uma aposentadoria integral a quem contribuiu por 15 anos ao INSS."], "gabarito": 3, "explicacao": "Art. 203, V, da CF e art. 20 da Lei 8.742/1993."}, {"materia": "prev", "texto_base": "", "enunciado": "Para receber o BPC, é preciso ter contribuído para o INSS?", "opcoes": ["Só se a pessoa tiver deficiência.", "Sim, por pelo menos 12 meses.", "Sim, por pelo menos 15 anos.", "Não, por ser benefício assistencial.", "Só se a pessoa tiver mais de 70 anos."], "gabarito": 3, "explicacao": "A assistência social não exige contribuição."}, {"materia": "prev", "texto_base": "", "enunciado": "Em regra, a carência do auxílio por incapacidade temporária é de", "opcoes": ["180 contribuições mensais.", "12 contribuições mensais.", "24 contribuições mensais.", "10 contribuições mensais.", "6 contribuições mensais."], "gabarito": 1, "explicacao": "Art. 25, I, da Lei 8.213/1991. Acidentes e doenças graves dispensam carência."}, {"materia": "pcd", "texto_base": "", "enunciado": "Pela LBI, a pessoa com deficiência tem direito a atendimento prioritário", "opcoes": ["somente nas agências bancárias.", "apenas nos transportes coletivos municipais e intermunicipais.", "só nos órgãos federais.", "nos serviços públicos e privados de atendimento.", "apenas nos hospitais públicos."], "gabarito": 3, "explicacao": "Art. 9º, II, da Lei 13.146/2015."}, {"materia": "pcd", "texto_base": "", "enunciado": "Pela LBI, os sites mantidos por órgãos públicos devem", "opcoes": ["ser acessíveis às pessoas com deficiência.", "exigir cadastro com senha para todo acesso.", "ser acessados só no horário de expediente.", "funcionar apenas em computadores de mesa.", "ter versão só em língua estrangeira."], "gabarito": 0, "explicacao": "Art. 63 da Lei 13.146/2015."}, {"materia": "pcd", "texto_base": "", "enunciado": "Pela Lei 8.213/1991, a empresa com 100 ou mais empregados deve preencher parte das vagas com pessoas com deficiência ou reabilitadas, no percentual de", "opcoes": ["10% a 20%.", "5% a 10%.", "2% a 5%.", "20% a 30%.", "1% a 2%."], "gabarito": 2, "explicacao": "Art. 93 da Lei 8.213/1991."}, {"materia": "ia", "texto_base": "", "enunciado": "Pela LGPD, diante de decisão tomada só com base em tratamento automatizado de dados, o titular pode", "opcoes": ["impedir qualquer uso de computador.", "escolher outro servidor para decidir.", "receber indenização automática.", "exigir a exclusão do órgão.", "pedir a revisão da decisão."], "gabarito": 4, "explicacao": "Art. 20 da Lei 13.709/2018."}, {"materia": "ia", "texto_base": "", "enunciado": "Na inteligência artificial generativa, o prompt é", "opcoes": ["o vírus que ataca o sistema.", "o relatório final do sistema.", "a senha de acesso ao sistema.", "a instrução ou pergunta dada ao sistema.", "o computador ou servidor que roda o sistema."], "gabarito": 3, "explicacao": "É o comando que orienta a resposta."}, {"materia": "sust", "texto_base": "", "enunciado": "Entre os objetivos da Lei 14.133/2021 está", "opcoes": ["escolher sempre o fornecedor mais antigo do mercado.", "incentivar a inovação e o desenvolvimento sustentável.", "proibir a participação de micro e pequenas empresas.", "garantir lucro mínimo às empresas contratadas.", "dispensar a licitação em todas as compras públicas."], "gabarito": 1, "explicacao": "Art. 11, IV, da Lei 14.133/2021."}, {"materia": "sust", "texto_base": "", "enunciado": "A Agenda Ambiental na Administração Pública (A3P) busca", "opcoes": ["fiscalizar a pesca e a caça em áreas de preservação.", "proibir o uso de papel em todos os órgãos públicos do país.", "aplicar multas ambientais às empresas privadas poluidoras.", "substituir os servidores por sistemas automatizados.", "inserir critérios socioambientais nos órgãos públicos."], "gabarito": 4, "explicacao": "Programa do Ministério do Meio Ambiente."}, {"materia": "sust", "texto_base": "", "enunciado": "Na coleta seletiva solidária do governo federal, os resíduos recicláveis dos órgãos são destinados a", "opcoes": ["associações e cooperativas de catadores.", "incineradores dos próprios órgãos.", "servidores que se candidatarem.", "empresas privadas de reciclagem, por leilão.", "aterros sanitários do município."], "gabarito": 0, "explicacao": "Decreto 10.936/2022, que regulamenta a Política Nacional de Resíduos Sólidos."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('administrativa', date '2026-11-08', 'Simulado 1 · Administrativa', 'FGV', 240, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data - 1 as abre_sabado, s.data as fecha_domingo, s.titulo, s.estilo, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.data >= date '2026-11-08'
 group by s.id order by s.data, s.trilha;
